function defaultEndpoint(){return ['terminal.local','localhost','127.0.0.1'].includes(location.hostname)?`${location.protocol==='https:'?'wss':'ws'}://${location.host}/socket`:((import.meta as any).env.VITE_SERVER_URL||'');}
function setupLocal(sandbox=false){renderer.motionPreview='off';renderer.chipEffects.clear();autoDriver=false;closeBoard(false);disconnect();mode='local';sim?.dispose();sim=new Simulation({gameMode:sandbox?'ffa':matchMode,friendlyFire,wins:setsToWin,roundsPerSet,randomMapEachSet:!sandbox&&randomMapEachSet,map:sandbox?'foundry':selectedMap,bothDraft,sandbox,draftChoices,selectionSeconds:draftSeconds,skipBotDrafts:pref.skipBotDrafts===true,skipIntros:pref.skipIntros});id='local';sim.addPlayer(id,pref.name,chosenClass,null,pref.color,pref.cosmetics,accountAccess);const botClass:ClassId=chosenClass==='melee'?'ranged':chosenClass==='magic'?'melee':'magic';sim.addPlayer('bot',sandbox?'Target Dummy':`${difficulty[0].toUpperCase()+difficulty.slice(1)} Bot`,botClass,sandbox?'dummy':difficulty,'#ecae78');if(!sandbox){sim.configureLobby({map:selectedMap,botCount:practiceBots,botDifficulty:difficulty,botWeapons:practiceWeapons,botTeams:practiceTeams},id);sim.setTeam(id,practiceTeam);}sim.setReady(id,true);state=sim.snapshot();screen='game';paused=false;debugVisible=sandbox;yaw=0;pitch=-.06;seq=1;snapshots.clear();sound.reset();renderer.lastEvent=0;renderer.trails.clear();renderer.deathEffects.clear();renderer.impactGlows.clear();if(sandbox){sim.selectSpec(id,CLASS_INFO[chosenClass].default);sim.selectSpec('bot',CLASS_INFO[botClass].default);sim.phase='fight';sim.fightStart=sim.time;}connection=sandbox?'LOCAL SANDBOX':'LOCAL PRACTICE';drawMenu(true);drawSandbox();}
function disconnect(){killcam.clear();pveReset();spectator.enabled=false;spectator.target=undefined;peerRoom?.close();peerRoom=null;peerLost=false;ws?.close();ws=null;predictor?.dispose();predictor=null;roomCode='';onlineCode='';snapshots.clear();networkMetrics.reset();rtt=0;latestArrival=0;networkTime=0;}
function send(value:any){if(peerRoom){const room=peerRoom;if(latency)setTimeout(()=>{if(peerRoom===room)room.send(value);},latency);else room.send(value);return;}if(ws?.readyState===WebSocket.OPEN){if(latency>0)setTimeout(()=>{if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify(value));},latency);else ws.send(JSON.stringify(value));}}
function command(type:string,data:any={}){if(type==='pve'){if(mode==='online')send(pveNonce.wrap(data as PveCommand));return;}if(mode==='online')send({type,...data});else if(type==='spec')sim.selectSpec(id,data.id);else if(type==='chip')sim.selectChip(id,data.id);else if(type==='debug')sim.debug(data.command,id);else if(type==='ready')sim.setReady(id,data.ready);else if(type==='team')sim.setTeam(data.target||id,data.team);else if(type==='class')sim.setClass(id,data.class);else if(type==='rematch')sim.rematch();else if(type==='lobby')sim.requestLobbyReturn();else if(type==='cancel-lobby')sim.cancelLobbyReturn();else if(type==='settings')sim.configureLobby(data,id);if(mode==='local')state=sim.snapshot();drawMenu(true);}
function connect(endpoint:string,join:boolean,code:string,rejoinWith=''){let url:URL;try{url=new URL(endpoint);if(!['ws:','wss:'].includes(url.protocol))throw Error();if(location.protocol==='https:'&&url.protocol!=='wss:'){notice('Use a secure wss:// backend from this HTTPS page. Use localhost for ws:// testing.');return;}}catch{notice('Enter the WebSocket URL of your running server. Example: ws://localhost:8788/socket');return;}disconnect();autoDriver=false;seq=0;connection='CONNECTING';notice('Connecting to server…');const socket=roomSocket(url);ws=socket;let welcomed=false;const timeout=setTimeout(()=>{if(!welcomed){socket.close();notice('Connection timed out. Check that the server is running and reachable.');}},8000);
 socket.onopen=()=>{if(ws!==socket)return;socket.send(JSON.stringify({type:join?'join':'create',code,name:pref.name,color:pref.color,cosmetics:pref.cosmetics,authToken,class:chosenClass,gameMode:matchMode,friendlyFire,wins:setsToWin,roundsPerSet,randomMapEachSet,map:selectedMap,botCount:roomBots,botDifficulty:difficulty,bothDraft,draftChoices,selectionSeconds:draftSeconds,skipBotDrafts:pref.skipBotDrafts===true,skipIntros:pref.skipIntros,...(bossCreate&&!join?{pve:bossCreate}:{}),...(rejoinWith?{rejoin:rejoinWith}:{})}));};socket.onmessage=e=>{if(ws!==socket)return;const process=()=>{if(ws!==socket)return;let m:any;try{m=JSON.parse(e.data);}catch{return;}if(m.type==='welcome'){clearTimeout(timeout);welcomed=true;mode='online';id=m.id;roomCode=m.code;onlineCode=onlineRoomCode(m.onlineCode)?m.onlineCode:'';publicOrigin=publicInviteOrigin(m.inviteOrigin);screen='lobby';paused=false;connection='SERVER · WEBSOCKET';roomOwner=m.owner;predictor=new Predictor();pveHello.enter(m.code);lastEndpoint=endpoint;if(m.rejoined){rejoin.succeeded();notice('Rejoined the boss fight.');}if(pref.dedicated){pref.endpoint=endpoint;save();}notice('Connected. Room '+roomCode);}
 else if(m.type==='snapshot'){if(!snapshots.push(m.state))return;networkMetrics.snapshot(snapshotBytes=new TextEncoder().encode(e.data).length);state=pveFixture.apply(m.state as Snapshot);pveSnapshot();killcam.observe(state,id);latestArrival=performance.now();const me=getMe();if(me&&predictor)predictor.reconcile(state,me);if(screen==='lobby'&&state.phase!=='lobby'){screen='game';yaw=me?.yaw||0;pitch=-.06;sound.reset();renderer.lastEvent=0;renderer.trails.clear();renderer.deathEffects.clear();renderer.impactGlows.clear();}if((screen==='game'||screen==='settings'&&paused)&&state.phase==='lobby'){screen='lobby';paused=false;document.querySelector('#sandbox')!.innerHTML='';document.exitPointerLock?.();}drawMenu();}
 else if(m.type==='invite'){publicOrigin=publicInviteOrigin(m.origin);onlineCode=onlineRoomCode(m.onlineCode)?m.onlineCode:'';drawMenu(true);}else if(m.type==='owner'){roomOwner=m.id;drawMenu(true);}else if(m.type==='pong'){if(networkMetrics.pong(m))rtt=networkMetrics.rtt;}else if(m.type==='error'&&rejoin.phase==='connecting'){rejoin.failed(performance.now(),m.message);ws?.close();}else if(m.type==='notice'||m.type==='error')notice(m.message);else if(m.type==='rematchVotes'&&votes(m.count))notice(`${m.count}/${state.players.filter(p=>p.connected&&!p.bot).length} pilots ready for rematch.`);};if(latency)setTimeout(process,latency);else process();};socket.onclose=event=>{clearTimeout(timeout);if(ws!==socket)return;if(pveLost())return;connection='DISCONNECTED';notice(`Connection closed (${event.code}${event.reason?': '+event.reason:''}). Return to the menu to reconnect.`);};socket.onerror=()=>notice('Could not reach the multiplayer server. Check the URL, TLS, and server startup.');}
async function connectByCode(value:string){const code=onlineRoomCode(value);if(!code)return;const button=document.querySelector<HTMLButtonElement>('[data-action="connect"]');if(button)button.disabled=true;connectionError='';notice('Finding the host from the room code…');try{const response=await fetch(`${DIRECTORY_ORIGIN}/api/directory/${code}`,{cache:'no-store',redirect:'error',signal:AbortSignal.timeout(8000)});if(response.status===404)throw Error('Room code expired or was not found. Ask the host to keep their room open.');if(!response.ok)throw Error('Room lookup is temporarily unavailable. Ask the host for an invite link.');const data=await response.json(),origin=publicInviteOrigin(data.origin);if(data.code!==code||!origin)throw Error('Invalid room lookup response.');if(screen!=='join')return;connect(origin.replace(/^https:/,'wss:')+'/socket',true,code);}catch(e){connectionError=e instanceof Error?e.message:'Could not find this room.';notice(connectionError);drawMenu(true);}finally{if(button?.isConnected)button.disabled=false;}}
function connectBrowser(join:boolean,code:string){connectionError='';if(join&&!normalizeRoomCode(code)){notice('Enter the 8-character room code from your host.');return;}disconnect();closeBoard(false);connection=join?'JOINING ROOM':'CREATING ROOM';notice(join?'Finding the host…':'Creating your room…');autoDriver=false;seq=0;
 try{const room=new BrowserRoom(!join,code,{name:pref.name,class:chosenClass,color:pref.color,cosmetics:pref.cosmetics,authToken},bothDraft,m=>{if(peerRoom!==room)return;const process=()=>receivePeerMessage(m);if(latency)setTimeout(()=>{if(peerRoom===room)process();},latency);else process();},label=>{connection=label;},reason=>{peerLost=true;connection='DISCONNECTED';connectionError=reason;notice(reason);drawMenu(true);if(mode==='online'){state={...state,phase:'match',winner:null,result:reason};screen='game';paused=false;drawMenu(true);}},draftChoices,pref.skipIntros,draftSeconds,{skipBotDrafts:pref.skipBotDrafts===true,gameMode:matchMode,friendlyFire,wins:setsToWin,roundsPerSet,randomMapEachSet,map:selectedMap,botCount:roomBots,botDifficulty:difficulty,...(bossCreate?{pve:bossCreate}:{})});peerRoom=room;}catch(e){connection='DISCONNECTED';connectionError=e instanceof Error?e.message:'Could not start browser hosting.';notice(connectionError);drawMenu(true);}}
function receivePeerMessage(m:any){if(m.type==='welcome'){mode='online';id=m.id;roomOwner=m.owner;roomCode=m.code;pveHello.enter(m.code);onlineCode=onlineRoomCode(m.onlineCode)?m.onlineCode:'';publicOrigin=publicInviteOrigin(m.inviteOrigin);screen='lobby';paused=false;predictor?.dispose();predictor=new Predictor();snapshots.clear();latestArrival=performance.now();notice(peerRoom instanceof LocalRoom?'Boss test starting…':id==='host'?'Room ready. Share the code or invite link.':'Joined room '+roomCode);}
 else if(m.type==='snapshot'){if(!snapshots.push(m.state))return;state=pveFixture.apply(m.state as Snapshot);pveSnapshot();killcam.observe(state,id);latestArrival=performance.now();const me=getMe();if(me&&predictor)predictor.reconcile(state,me);if(screen==='lobby'&&state.phase!=='lobby'){screen='game';yaw=me?.yaw||0;pitch=-.06;sound.reset();renderer.lastEvent=0;renderer.trails.clear();renderer.deathEffects.clear();renderer.impactGlows.clear();}if((screen==='game'||screen==='settings'&&paused)&&state.phase==='lobby'){screen='lobby';paused=false;document.querySelector('#sandbox')!.innerHTML='';document.exitPointerLock?.();}drawMenu();}
 else if(m.type==='owner'){roomOwner=m.id;drawMenu(true);}else if(m.type==='pong'){if(networkMetrics.pong(m))rtt=networkMetrics.rtt;}else if(m.type==='notice'||m.type==='error')notice(m.message);else if(m.type==='rematchVotes'&&votes(m.count))notice(`${m.count}/${state.players.filter(p=>p.connected&&!p.bot).length} pilots ready for rematch.`);}
function connectionReport(){return JSON.stringify({transport:connection,endpoint:ws?.url||location.origin,room:roomCode,phase:state.phase,players:state.players.length,fps:Math.round(renderer.fps),renderMs:+renderer.renderMs.toFixed(2),simulationTickMs:+state.metrics.tickMs.toFixed(2),hidden:document.hidden,pendingInputs:predictor?.pending.length||0,clientUploadQueueBytes:ws?.bufferedAmount||0,...networkMetrics.summary},null,2);}
function showConnectionReport(){document.exitPointerLock?.();if(screen==='game'){paused=true;drawMenu(true);}document.querySelector('#network-report-text')!.textContent=connectionReport();(document.querySelector('#network-report') as HTMLDialogElement).showModal();}
function inviteUrl(){return roomInviteUrl(inviteBase||(desktopHosting()?DIRECTORY_ORIGIN:location.href),roomCode,publicOrigin);}
async function copyInvite(link:boolean){const value=link?inviteUrl():onlineCode||roomCode;try{await navigator.clipboard.writeText(value);notice(link?'Invite link copied.':'Room code copied.');}catch{notice('Copy this '+(link?'invite: ':'code: ')+value);}}
// ---- PvE TEST BOSS glue (design §7). Builders and tracks live in ./pve/*; these functions only wire them to main's state.
function pveReset(){pveHello.leave();moneyTrack.clear();attackedTrack.clear();pveDelays.clear();chipsClosedUntil=0;chipRestoreLock=false;rematchVotes=0;bossAutoReady=false;snapshotBytes=0;}
function votes(count:number){rematchVotes=Number(count)||0;panelKey='';return true;}
/** After every received snapshot: the one hello per room entry (then the chip-screen preference and, offline, ready). */
function pveSnapshot(){if(state.phase!=='match')rematchVotes=0;const hello=pveHello.update(state,keyStore());if(!hello)return;send(pveNonce.wrap(hello));send(pveNonce.wrap({action:'prefs',autoOpen:pref.bossAutoOpenChips}));if(bossAutoReady){bossAutoReady=false;send({type:'ready',ready:true});}}
/** WebSocket closed: rejoin a PvE fight automatically (D33). Returns true when PvE handled the close. */
function pveLost(){const now=performance.now();if(rejoin.active){rejoin.failed(now);connection=rejoin.active?'REJOINING':'DISCONNECTED';notice(rejoin.active?`Connection lost — rejoining (attempt ${rejoin.attempts+1} of 3)…`:`Could not rejoin the boss fight${rejoin.error?': '+rejoin.error:''}. Return to the menu.`);return true;}
 if(!state.options.pve||!rejoin.lost(now,{websocket:true,pve:true,phase:state.phase,left:leftRoom,code:roomCode}))return false;connection='REJOINING';notice('Connection lost — rejoining in 2 s…');return true;}
/** Start Boss Fight: offline in the host worker, or hosted (desktop app, dedicated server, browser relay) when "Host online" is checked. */
function startBoss(){bossCreate={boss:'siren',skipWaves:pref.bossSkipWaves,partyBots:pref.bossPartyBots};rejoin.reset();leftRoom=false;connectionError='';pveFixture.set(null,state,id);
 if(!pref.bossHostOnline){closeBoard(false);renderer.motionPreview='off';autoDriver=false;disconnect();seq=0;const room=new LocalRoom({name:pref.name,class:chosenClass,color:pref.color,cosmetics:pref.cosmetics,authToken},{pve:bossCreate,local:true},m=>{if(peerRoom===room)receivePeerMessage(m);},label=>{connection=label;},reason=>{if(peerRoom!==room)return;peerLost=true;connection='DISCONNECTED';connectionError=reason;notice(reason);state={...state,phase:'match',winner:null,result:reason};screen='game';paused=false;drawMenu(true);},{skipIntros:pref.skipIntros,draftChoices,selectionSeconds:draftSeconds});peerRoom=room;bossAutoReady=true;mode='online';connection='LOCAL BOSS TEST';notice('Starting the boss test…');return;}
 if(desktopHosting()){void createDesktopRoom(true);return;}
 if(pref.dedicated||automaticEndpoint){connect(pref.dedicated?pref.endpoint||defaultEndpoint():automaticEndpoint!,false,'');return;}
 connectBrowser(false,'');}
function readBossPrefs(t:HTMLInputElement){if(t.id==='boss-host-online')pref.bossHostOnline=t.checked;else if(t.id==='boss-skip-waves')pref.bossSkipWaves=t.checked;else if(t.id==='boss-auto-open'){pref.bossAutoOpenChips=t.checked;if(state.pve)command('pve',{action:'prefs',autoOpen:t.checked});}else if(t.id==='boss-party-bots')pref.bossPartyBots=bossPrefs({bossPartyBots:Number(t.value)}).bossPartyBots;else return;save();drawMenu(true);}
/** Reopen the chip screen (icon or C): the oldest pending pick, or the one already open. */
function openChips(){const pve=state.pve,row=pve?.party[id];if(!row||!row.picks.length||pve!.cinematic||state.phase!=='fight')return;chipsClosedUntil=0;if(!row.open)command('pve',{action:'open'});}
/** Choose later (button, C or Esc): the pick stays queued; control and pointer lock come back at once. */
function chooseLater(){if(!state.pve)return;command('pve',{action:'close'});chipsClosedUntil=performance.now()+1500;chipScreen?.update(state,id,false,false);chipRestoreLock=false;if(!paused)lock();drawHud();}
function pickChip(pick:string,chip:string){const row=state.pve?.party[id];command('pve',{action:'pick',pick,chip});if(row&&row.picks.length<=1){chipsClosedUntil=performance.now()+1500;chipScreen?.update(state,id,false,false);chipRestoreLock=false;if(!paused)lock();}}
/** PvE keys: C / Esc / 1–9 while the chip screen is open; C reopens it. Returns true when the key was handled. */
function pveKey(e:KeyboardEvent){if(!state.pve||(e.target as HTMLElement).matches?.('input,select,textarea'))return false;
 if(chipScreen?.visible){if(e.code==='Escape'||e.code==='KeyC'){e.preventDefault();if(!e.repeat)chooseLater();return true;}const n=/^Digit([1-9])$/.exec(e.code)?.[1];if(n){e.preventDefault();if(!e.repeat){const c=chipScreen.chipAt(Number(n));if(c)pickChip(c.pick,c.chip);}return true;}return false;}
 if(e.code==='KeyC'&&!e.repeat&&!paused&&state.phase==='fight'&&state.pve.party[id]?.picks.length){openChips();return true;}return false;}
/** Idle input during holds, while my chip screen is open and while I channel a revive (F stays held so it continues). */
function pveIdle(){const pve=state?.pve;return !!pve&&state.phase==='fight'&&(pve.hold||!!chipScreen?.visible||!!pve.party[id]?.channel);}
/** The PvE HUD widgets (§7.3), replacing .match-heading. */
function pveHud(pve:PveView,me:PlayerView){pveDelays.frame(state.time,state.generation||0);const banner=bannerFor(state,pve,id);
 return moneyHud(pve,id,moneyTrack.update(state,id))+(bossBar(state,pve)||waveHeading(pve,state.time))+partyHud(state,pve,id)+chipLaterIcon(pve,id,state.time,!!chipScreen?.visible)+pveBanner(banner,banner?pveDelays.delay(banner.key,banner.at):0)+(me.hp>0&&!chipScreen?.visible?promptHud(promptFor(state,pve,id)):'')+possessionArrow(state,pve,id,yaw);}
/** Every frame: body.pve layout, worker pause, rejoin attempts, the chip screen and the reveal overlay. */
function pveFrame(now:number){const pve=state.pve,active=screen==='game';document.body.classList.toggle('pve',!!pve&&active);
 if(peerRoom instanceof LocalRoom)peerRoom.pause(paused);
 if(rejoin.due(now)&&lastEndpoint){connection='REJOINING';connect(lastEndpoint,true,rejoin.code,rejoinKey(rejoin.code,keyStore()));}
 const visible=active&&!paused&&!killcam.active&&!!pve&&chipScreenVisible(state,id,now<chipsClosedUntil);
 if(visible&&chipScreen&&!chipScreen.visible){chipRestoreLock=document.pointerLockElement===canvas;keys.clear();left=right=pendingBlock=false;closeBoard(false);document.exitPointerLock?.();}
 chipScreen?.update(state,id,visible,visible&&attackedTrack.update(state,id).attacked);
 revealOverlay?.update(active&&!paused&&pve?(presentedState||state):undefined);
 if(pve&&mode==='online'&&!ws&&now-snapshotSampleAt>2000){snapshotSampleAt=now;snapshotBytes=JSON.stringify(state).length;}}
function pveMetrics(){const h=renderer?.pve.metrics();return {draws:(renderer?.renderer as any)?.info?.render?.calls??0,snapshotBytes,pveAdds:state?.pve?.adds.length??0,fullRigs:h?.fullRigs??0,nearImpostors:h?.nearImpostors??0};}
function startBossApi(cls:ClassId=pref.class,o:{online?:boolean;partyBots?:number;skipWaves?:boolean}={}){chosenClass=allowedClass(cls,accountAccess);Object.assign(pref,bossPrefs({...pref,bossHostOnline:o.online===true,bossPartyBots:o.partyBots??0,bossSkipWaves:o.skipWaves===true}));save();screen='test-boss';startBoss();}
/** DEV fixture injection (§7.8): DEV builds and DEV accounts only. */
function setFixture(name:PveFixtureName|PveView|null){if(!(import.meta as any).env.DEV&&!developer)throw Error('PvE fixtures need a DEV build or a DEV account.');if(typeof name==='string'&&!PVE_FIXTURE_NAMES.includes(name))throw Error('Unknown fixture: '+name);moneyTrack.clear();attackedTrack.clear();pveDelays.clear();chipsClosedUntil=0;const view=pveFixture.set(name,state,id);state=pveFixture.apply(state);panelKey='';lastHud=0;drawMenu(true);return view?{fixture:pveFixture.name,stage:view.stage}:null;}
