function readSettings(){pref.graphics=(document.querySelector('#graphics') as HTMLSelectElement).value as GraphicsMode;renderer.setGraphics(pref.graphics);pref.sensitivity=Number((document.querySelector('#sensitivity')as HTMLInputElement).value);pref.audio=Number((document.querySelector('#audio')as HTMLInputElement).value);pref.music=Number((document.querySelector('#music-volume')as HTMLInputElement).value);pref.menuMusic=Number((document.querySelector('#menu-music-volume')as HTMLInputElement).value);pref.camera=(document.querySelector('#camera-mode')as HTMLSelectElement).value==='first'?'first':'third';pref.muted=(document.querySelector('#muted')as HTMLInputElement).checked;pref.trails=(document.querySelector('#trails')as HTMLInputElement).checked;pref.effects=Number((document.querySelector('#effects')as HTMLSelectElement).value);pref.shake=(document.querySelector('#shake')as HTMLInputElement).checked;pref.endpoint=(document.querySelector('#endpoint')as HTMLInputElement).value.trim();pref.dedicated=(document.querySelector('#dedicated')as HTMLInputElement).checked;latency=Math.max(0,Math.min(1000,Number((document.querySelector('#latency')as HTMLInputElement)?.value)||0));save();renderer.effectsQuality=pref.effects;renderer.shake=pref.shake;renderer.setCameraMode(pref.camera);renderer.projectileTrails=pref.trails;sound.configure(pref.audio,pref.muted);sound.music.configure(pref.music,pref.muted,pref.menuMusic);}
