ui.addEventListener('input',e=>{const target=e.target as HTMLInputElement;if(screen==='settings'&&target.id==='menu-music-volume'){pref.menuMusic=Number(target.value);sound.music.configure(pref.music,pref.muted,pref.menuMusic);sound.music.unlock();const value=document.querySelector('#menu-music-value');if(value)value.textContent=Math.round(pref.menuMusic*100)+'%';save();return;}if(screen!=='customize')return;if(target.id==='body-color')pref.cosmetics.bodyColor=target.value;else if(target.id==='accent-color')pref.color=target.value;else if(target.id==='preferred-weapon'){pref.cosmetics.preferredSpec=preferredWeapon(target.value,pref.class,accountAccess);drawMenu(true);}else if(target.id==='pilot-hat')pref.cosmetics.hat=target.value as keyof typeof HATS;else if(target.id==='pilot-kill'){pref.cosmetics.killEffect=target.value as keyof typeof KILL_STYLES;if(accounts.account)rememberKillEffect(localStorage,accounts.account.id,pref.cosmetics.killEffect,accounts.account.profile.cosmetics.killEffect,accountAccess);}else if(target.id==='override-weapon-intro'){pref.cosmetics.overrideWeaponIntro=target.checked;const select=document.querySelector<HTMLSelectElement>('#pilot-intro');if(select){select.disabled=!target.checked;select.options[Array.from(select.options).findIndex(o=>o.value==='neon-drop')].text=target.checked?'Neon Drop':'Weapon Signature';}}else if(target.id==='pilot-intro')pref.cosmetics.intro=target.value as keyof typeof INTRO_STYLES;else if(target.id==='pilot-intro-text')pref.cosmetics.introText=introText(target.value);else if(target.id==='name')pref.name=target.value.trim().slice(0,20)||'Pilot';else return;const p=sim.players.get('local');if(p){p.name=pref.name;p.color=pref.color;p.cosmetics={...pref.cosmetics};p.class=pref.class;p.spec=preferredWeapon(pref.cosmetics.preferredSpec,pref.class,accountAccess);}const label=document.querySelector('.pilot-showcase .pilot-card-name strong');if(label)label.textContent=pref.name;save();});
ui.addEventListener('change',e=>{const target=e.target as HTMLSelectElement;if(target.id==='sandbox-kill'){command('debug',{command:{action:'cosmetics',...getMe()?.cosmetics,killEffect:target.value}});}});

function applyAccount(loadPilot=false){const a=accounts.account;if(!a)return;authToken=accounts.token;developer=a.developer;accountAccess={accountId:a.id,developer:a.developer,unlocks:a.unlocks,flags:a.flags};sessionStorage.removeItem('chip-arena-dev-session');if(loadPilot&&a.hasProfile){Object.assign(pref,{...a.profile,cosmetics:{...a.profile.cosmetics,killEffect:restoreKillEffect(localStorage,a.id,a.profile.cosmetics.killEffect,accountAccess)}});chosenClass=pref.class;}pref.class=allowedClass(pref.class,accountAccess);chosenClass=allowedClass(chosenClass,accountAccess);pref.cosmetics=cosmetics(pref.cosmetics,accountAccess);save();const p=sim?.players.get('local');if(p){Object.assign(p,accountAccess);p.flags=a.flags||[];p.cosmetics={...pref.cosmetics};p.name=pref.name;p.color=pref.color;p.class=allowedClass(p.class,accountAccess);if(WEAPONS[p.spec].devOnly&&!canUse(accountAccess,'weapon:'+p.spec))p.spec=CLASS_INFO[p.class].default;}}
async function refreshAccount(loadPilot=false){try{await accounts.refresh();applyAccount(loadPilot);notice(loadPilot?'Saved pilot loaded.':'Account and unlocks refreshed.');drawMenu(true);}catch(e:any){notice(e.message);}}
async function saveAccountPilot(){
 if(!accounts.account){screen='login';drawMenu(true);return;}
 const accountId=accounts.account.id,profile={name:pref.name,class:pref.class,color:pref.color,cosmetics:{...pref.cosmetics}};
 try{
  rememberKillEffect(localStorage,accountId,profile.cosmetics.killEffect,accounts.account.profile.cosmetics.killEffect,accountAccess);
  const saved=await accounts.save(profile);if(!saved||saved.id!==accountId)return;
  const localOnly=rememberKillEffect(localStorage,accountId,pref.cosmetics.killEffect,saved.profile.cosmetics.killEffect,saved);
  applyAccount();notice(localOnly?'Pilot saved. Kill effect kept on this device; cloud sync did not retain it.':'Pilot saved to your account.');drawMenu(true);
 }catch(e:any){notice(e.message);}
}
async function logoutAccount(){try{await accounts.logout();}catch(e:any){notice('Signed out on this device. Server logout could not be confirmed.');}authToken='';developer=false;accountAccess={developer:false,unlocks:[]};sessionStorage.removeItem('chip-arena-dev-session');pref.class=allowedClass(pref.class);chosenClass=allowedClass(chosenClass);pref.cosmetics=cosmetics(pref.cosmetics);save();const p=sim?.players.get('local');if(p){p.developer=false;p.unlocks=[];p.accountId=undefined;p.flags=[];p.cosmetics={...pref.cosmetics};p.class=allowedClass(p.class,accountAccess);if(WEAPONS[p.spec].devOnly)p.spec=CLASS_INFO[p.class].default;}screen='home';drawMenu(true);notice('Logged out. Your saved pilot stays on your account.');}
ui.addEventListener('submit',async e=>{
 const form=e.target as HTMLFormElement;if(!['login-form','dev-search'].includes(form.id)&&!form.matches('.dev-player'))return;e.preventDefault();const button=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,error=form.querySelector('.grant-result')||form.querySelector('#login-error')||document.querySelector('#dev-error')!;button.disabled=true;error.textContent='Working…';
 try{
  if(form.id==='login-form'){const username=(form.querySelector('#login-user')as HTMLInputElement).value,password=(form.querySelector('#login-password')as HTMLInputElement).value;await accounts.login(accountForm,username,password,(form.querySelector('#recovery-code')as HTMLInputElement)?.value,(form.querySelector('#remember-login')as HTMLInputElement).checked);applyAccount(true);if(!accounts.account!.hasProfile){const code=accounts.recoveryCode;await accounts.save({name:pref.name,class:pref.class,color:pref.color,cosmetics:pref.cosmetics});accounts.recoveryCode=code;applyAccount();}screen='account';notice('Signed in as '+accounts.account!.username+'.');drawMenu(true);}
  else if(form.id==='dev-search'){const data=await accounts.request('players',{query:(form.querySelector('#dev-query')as HTMLInputElement).value});managedPlayers=data.players;drawMenu(true);document.querySelector('#dev-error')!.textContent=managedPlayers.length?managedPlayers.length+' registered player(s) found.':'No registered players match that username.';}
  else{const a=managedPlayers.find(p=>p.id===form.dataset.playerId);if(!a)throw Error('Search for this player again.');const values=(name:string)=>Array.from(form.querySelectorAll<HTMLInputElement>('input[name="'+name+'"]:checked')).map(x=>x.value);const data=await accounts.request('grant',{accountId:a.id,grantVersion:a.grantVersion,unlocks:values('grant'),flags:values('flag')});Object.assign(a,data.account);error.textContent='Saved. Ask the player to refresh their account and rejoin their room.';}
 }catch(e:any){error.textContent=e.message||'Account request failed.';}finally{if(button.isConnected)button.disabled=false;}
});
// Refresh short-lived game claims before they expire. Account sessions never go to a match host.
setInterval(()=>{if(accounts.session)void accounts.refresh().then(()=>applyAccount()).catch(()=>{});},5*60*1000);
